{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plan a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fffe;--card:#ffffff;--accent:#0f6b67;--muted:#516b6b}
    body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto;background:var(--bg) url('assets/img/pattern.svg');color:#05282a}
    header{padding:14px 20px;border-bottom:1px solid rgba(5,8,10,0.04)}
    .nav{max-width:1100px;margin:0 auto;display:flex;gap:14px;align-items:center}
    .container{max-width:1100px;margin:28px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:20px}
    h1{margin:0 0 6px}
    p.lead{color:var(--muted)}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 26px rgba(8,20,20,0.04)}
    label{display:block;margin-bottom:6px;color:#083233}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(8,20,20,0.06)}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;display:inline-block}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 500ms ease,transform 500ms ease}
    .revealed{opacity:1;transform:none}
    .planner-form{display:flex;flex-direction:column;gap:10px}
    .summary{white-space:pre-wrap;background:#f2fffc;padding:12px;border-radius:8px;border:1px dashed rgba(10,20,20,0.04);font-family:Menlo,monospace}
    @media (max-width:950px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <nav class="nav">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <a href="index.html">Overview</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Journeys</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html" aria-current="page">Plan a Session</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="container">
    <section class="reveal" data-reveal>
      <h1>Design a concise session that fits your day</h1>
      <p class="lead">Use the planner to map a practical session. Export the summary to bring to an intake or keep for your weekly review.</p>
    </section>

    <section class="grid" style="margin-top:18px">
      <div class="card reveal" data-reveal>
        <form id="session-planner" class="planner-form" aria-label="Session planner">
          <div>
            <label for="name">Your name</label>
            <input id="name" name="name" type="text" placeholder="Your name or initials" />
          </div>
          <div>
            <label for="context">Context / constraint for this period</label>
            <input id="context" name="context" type="text" placeholder="e.g., traveling, busy deadline" />
          </div>
          <div>
            <label for="goal">Top outcome you want in four weeks</label>
            <input id="goal" name="goal" type="text" placeholder="A concise measurable aim" />
          </div>
          <div>
            <label for="rhythm">Preferred rhythm</label>
            <select id="rhythm" name="rhythm">
              <option>Weekly session + micro-checks</option>
              <option>Twice weekly focus</option>
              <option>Three short check-ins</option>
            </select>
          </div>
          <div>
            <label for="tools">Tools you already use</label>
            <input id="tools" name="tools" type="text" placeholder="Calendar, habit tracker, notes" />
          </div>
          <div>
            <label for="notes">Any other notes</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Barriers, schedule windows, accountability"></textarea>
          </div>
          <div style="display:flex;gap:8px;align-items:center;margin-top:6px">
            <button id="generate" type="button" class="btn">Create plan</button>
            <a href="{{PRIMARY_CTA_URL}}" class="btn" style="background:#0b504e">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </form>
      </div>

      <aside class="card reveal" data-reveal>
        <h3 style="margin-top:0">Plan summary</h3>
        <div id="summary" class="summary" aria-live="polite">Use the form to generate a compact session plan. You can copy the text and paste into an email or note.</div>
        <div style="display:flex;gap:8px;margin-top:10px">
          <button id="copy" class="btn">Copy text</button>
          <button id="download" class="btn" style="background:#1e7c79">Download .txt</button>
        </div>
        <div style="margin-top:12px;color:var(--muted);font-size:13px">Prefer a phone call? <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </aside>
    </section>

    <section class="reveal" data-reveal style="margin-top:20px">
      <h2 style="margin:0 0 8px">What to expect from a first meeting</h2>
      <p class="lead">A short intake focuses on clarifying the immediate outcome and identifying 2–3 habits to try. Emphasis is on making those actions realistic and repeatable.</p>
    </section>
  </main>

  <footer style="max-width:1100px;margin:28px auto;padding:20px;color:var(--muted)">
    <div>Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    // Scroll reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(reduced){ items.forEach(i=>i.classList.add('revealed')); return }
      const observer = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('revealed'); observer.unobserve(e.target) } });
      },{threshold:0.12});
      items.forEach(i=>observer.observe(i));
    })();

    // Session planner: build a concise plaintext plan and support copy + download
    (function(){
      const form = document.getElementById('session-planner');
      const gen = document.getElementById('generate');
      const summary = document.getElementById('summary');
      const copyBtn = document.getElementById('copy');
      const dl = document.getElementById('download');

      function buildText(vals){
        const lines = [];
        lines.push('Session Plan — ' + (vals.name || 'Anonymous'));
        lines.push('Site: ' + '{{CITY}}, {{STATE}}');
        lines.push('Goal: ' + (vals.goal || 'Establish a reliable practice'));
        lines.push('Context: ' + (vals.context || 'None specified'));
        lines.push('Rhythm: ' + vals.rhythm);
        lines.push('Tools: ' + (vals.tools || 'None'));
        lines.push('');
        lines.push('Immediate actions (first 2 weeks):');
        const actions = suggestedActions(vals);
        actions.forEach((a,i)=>lines.push((i+1)+'. '+a));
        lines.push('');
        lines.push('Check-in cadence: review every week and adjust micro-habits as needed.');
        if(vals.notes) { lines.push('Notes: ' + vals.notes) }
        return lines.join('\n');
      }

      function suggestedActions(v){
        const out = [];
        // simple heuristics to create actions
        if(v.rhythm.includes('Weekly')){
          out.push('One 40-minute working session each week dedicated to the top goal');
          out.push('Daily 3-minute micro-checks tied to an existing habit (e.g., after coffee)');
        }else if(v.rhythm.includes('Twice')){
          out.push('Two focused sessions per week (planning + review)');
          out.push('End-of-day 5-minute note to capture what worked');
        }else{
          out.push('Three short 20-minute check-ins spread through the week');
          out.push('Use a single tracker to mark completion after each check-in');
        }
        if(v.tools && v.tools.toLowerCase().includes('calendar')){
          out.push('Block session time in calendar and set two reminders');
        }
        return out.slice(0,4);
      }

      gen.addEventListener('click',()=>{
        const data = {
          name: document.getElementById('name').value.trim(),
          context: document.getElementById('context').value.trim(),
          goal: document.getElementById('goal').value.trim(),
          rhythm: document.getElementById('rhythm').value,
          tools: document.getElementById('tools').value.trim(),
          notes: document.getElementById('notes').value.trim()
        };
        const txt = buildText(data);
        summary.textContent = txt;
      });

      copyBtn.addEventListener('click', async ()=>{
        try{
          await navigator.clipboard.writeText(summary.textContent);
          copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy text',1200);
        }catch(e){
          // fallback
          const ta = document.createElement('textarea'); ta.value = summary.textContent; document.body.appendChild(ta);
          ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
          copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy text',1200);
        }
      });

      dl.addEventListener('click', ()=>{
